interaction_history.observation:
[
  {
    "id": 0,
    "knowledge": "Temperature Excursion Duration (TED)",
    "description": "The total time a shipment spends outside its required temperature range during transit.",
    "definition": "TED = \\sum_{i=1}^{n} t_i, \\text{where } t_i \\text{ is the duration in minutes of each individual temperature excursion event.}"
  },
  {
    "id": 1,
    "knowledge": "Temperature Excursion Severity Index (TESI)",
    "description": "Measures the severity of temperature excursions relative to product temperature requirements.",
    "definition": "TESI = TED \\times \\frac{|T_{max} - T_{allowed}| + |T_{min} - T_{allowed}|}{2}, \\text{where } T_{max} \\text{ and } T_{min} \\text{ are the maximum and minimum temperatures recorded during excursions, and } T_{allowed} \\text{ is the allowed temperature range midpoint.}"
  },
  {
    "id": 2,
    "knowledge": "Critical Temperature Exposure",
    "description": "Indicates when a product has been exposed to temperatures that may significantly impact product quality.",
    "definition": "An exposure event where the product temperature deviates more than 5\u00b0C from its specified temperature range for more than 60 consecutive minutes."
  },
  {
    "id": 3,
    "knowledge": "Route Risk Classification",
    "description": "Categorizes shipping routes based on their risk level for temperature excursions.",
    "definition": "Routes are classified as: 'Low Risk' (0-1 historical excursion events per 10 shipments), 'Medium Risk' (2-4 historical excursion events per 10 shipments), 'High Risk' (5+ historical excursion events per 10 shipments)."
  },
  {
    "id": 4,
    "knowledge": "GDP Certification Status",
    "description": "Illustrates the certification levels for carriers in Good Distribution Practice.",
    "definition": "Carriers can have one of the following certification statuses: 'None' (no certification), 'GDP' (Good Distribution Practice certified), 'CEIV Pharma' (IATA Center of Excellence for Independent Validators certification), or 'Both' (having both GDP and CEIV Pharma certifications). Null values indicate pending certification status verification."
  },
  {
    "id": 5,
    "knowledge": "Cold Chain Compliance Rate (CCCR)",
    "description": "Measures the percentage of shipments that maintained required temperature conditions throughout transit.",
    "definition": "CCCR = \\frac{N_{compliant}}{N_{total}} \\times 100\\%, \\text{where } N_{compliant} \\text{ is the number of shipments with zero temperature excursions, and } N_{total} \\text{ is the total number of shipments.}"
  },
  {
    "id": 6,
    "knowledge": "Temperature Sensitivity Tiers",
    "description": "Classifies pharmaceutical products based on their sensitivity to temperature variations.",
    "definition": "Products are classified into three sensitivity tiers: 'Low' (can tolerate up to 24 hours of minor temperature deviations), 'Medium' (can tolerate up to 8 hours of minor temperature deviations), 'High' (cannot tolerate temperature deviations beyond 2 hours)."
  },
  {
    "id": 7,
    "knowledge": "Tier 1 Cold Chain Products",
    "description": "Identifies the highest value and most temperature-sensitive pharmaceutical products.",
    "definition": "Products with both a 'High' temperature sensitivity and a value exceeding $100,000 USD."
  },
  {
    "id": 8,
    "knowledge": "Temperature Monitoring Gap",
    "description": "Indicates periods where temperature data is missing during transit.",
    "definition": "A period of over 15 minutes where no temperature data points were recorded in a shipment that should have continuous monitoring."
  },
  {
    "id": 9,
    "knowledge": "Product Storage Classifications",
    "description": "Standardized temperature ranges for pharmaceutical product storage.",
    "definition": "Four standard storage classifications: '2-8\u00b0C' (refrigerated), '-20\u00b0C' (frozen), '-70\u00b0C' (ultra-low temperature), and '15-25\u00b0C' (controlled room temperature)."
  },
  {
    "id": 10,
    "knowledge": "Cold Chain Monitoring Compliance Score (CCMCS)",
    "description": "Evaluates the completeness and quality of monitoring data for a shipment.",
    "definition": "CCMCS = 0.4 \\times GPS\\% + 0.4 \\times Temp\\% + 0.2 \\times (100 - ER), \\text{where GPS\\% is the GPS completeness percentage, Temp\\% is the percentage of expected temperature readings received, and ER is the error rate of readings.}"
  },
  {
    "id": 11,
    "knowledge": "Critical Monitoring Failure",
    "description": "Indicates when monitoring systems fail to provide sufficient data to assess product quality.",
    "definition": "Occurs when either GPS completeness falls below 80% or when temperature monitoring has gaps exceeding 30 minutes during transit."
  },
  {
    "id": 12,
    "knowledge": "On-Time Delivery Performance (OTDP)",
    "description": "Measures how accurately shipments meet their planned delivery times.",
    "definition": "OTDP = \\frac{actual\\_duration}{planned\\_duration} \\times 100\\%, \\text{where a value of 100\\% indicates exact on-time delivery, <100\\% is early, and >100\\% is late delivery.}"
  },
  {
    "id": 13,
    "knowledge": "Delivery Performance Classification",
    "description": "Categorizes delivery performance based on variance from expected delivery time.",
    "definition": "Shipments are classified as: 'Early' (>2 hours before scheduled time), 'On-Time' (within \u00b12 hours of scheduled time), 'Delayed' (2-24 hours after scheduled time), 'Severely Delayed' (>24 hours after scheduled time)."
  },
  {
    "id": 14,
    "knowledge": "Quality Agreement Status",
    "description": "Illustrates the current state of quality agreements between parties in the cold chain.",
    "definition": "Quality agreements can have the following statuses: 'Active' (current agreement in force), 'Expired' (agreement has lapsed), 'Pending' (agreement under review), or null (no formal agreement exists)."
  },
  {
    "id": 15,
    "knowledge": "Carrier Performance Index (CPI)",
    "description": "Measures the overall performance of a carrier across multiple shipments.",
    "definition": "CPI = 0.4 \\times CCCR + 0.3 \\times (100 - ATNR) + 0.2 \\times (100 - ASDI) + 0.1 \\times DPR, \\text{where CCCR is Cold Chain Compliance Rate, ATNR is Average Temperature Non-conformance Rate, ASDI is Average Shock and Damage Incidents, and DPR is Documentation Problem Rate.}"
  },
  {
    "id": 16,
    "knowledge": "Major Pharmaceutical Markets",
    "description": "Identifies the primary global pharmaceutical markets for cold chain distribution.",
    "definition": "Major pharmaceutical markets include: United States, European Union (specifically Germany, France, Italy, Spain, and United Kingdom), Japan, China, Brazil, India, and Russia."
  },
  {
    "id": 17,
    "knowledge": "High-Risk Shipping Origin-Destination Pairs",
    "description": "Identifies shipping routes that historically show elevated risks for cold chain integrity.",
    "definition": "Shipping lane combinations that either: 1) cross more than three climate zones, 2) involve more than two carrier transfers, 3) include countries with historical customs delays exceeding 48 hours, or 4) have previously documented temperature excursion rates above 15%."
  },
  {
    "id": 18,
    "knowledge": "Location Tracking States",
    "description": "Illustrates the possible states of location tracking systems during transit.",
    "definition": "Location tracking can be in one of these states: 'Active' (providing regular updates), 'Intermittent' (occasional gaps in tracking), 'Failed' (no longer providing location data), or null (tracking was not implemented for this shipment)."
  },
  {
    "id": 19,
    "knowledge": "Packing Integrity Risk Factor (PIRF)",
    "description": "Quantifies the risk of packaging failure based on product, route, and handling conditions.",
    "definition": "PIRF = \\frac{S \\times D \\times T}{P}, \\text{where S is the shock event count, D is the distance in thousands of km, T is a temperature factor (1 for 15-25\u00b0C, 1.5 for 2-8\u00b0C, 2 for -20\u00b0C, 2.5 for -70\u00b0C), and P is the packaging robustness factor (1-10, with 10 being most robust).}"
  },
  {
    "id": 20,
    "knowledge": "Shipment Risk Score (SRS)",
    "description": "A comprehensive risk assessment score for cold chain shipments.",
    "definition": "SRS = 0.3 \\times TESI + 0.25 \\times PIRF + 0.25 \\times (100 - CCMCS) + 0.2 \\times RRF, \\text{where TESI is Temperature Excursion Severity Index, PIRF is Packing Integrity Risk Factor, CCMCS is Cold Chain Monitoring Compliance Score, and RRF is Route Risk Factor (1-10 based on Route Risk Classification).}"
  },
  {
    "id": 21,
    "knowledge": "Regulatory Compliance Status Definitions",
    "description": "Explains the different compliance status classifications used in quality assessment.",
    "definition": "Compliance statuses are defined as: 'Compliant' (meets all regulatory requirements), 'Non-compliant' (fails to meet one or more critical requirements), 'Under Review' (compliance being assessed), or null (compliance status not yet determined)."
  },
  {
    "id": 22,
    "knowledge": "Temperature-Sensitive Product Categories",
    "description": "The main categories of pharmaceutical products requiring temperature-controlled transport.",
    "definition": "Temperature-sensitive product categories include: Vaccines, Biologics (including monoclonal antibodies and recombinant proteins), Blood Products (including plasma and platelets), and Insulin products."
  },
  {
    "id": 23,
    "knowledge": "Shock Event Significance Levels",
    "description": "Classifies impact events based on their potential to damage pharmaceutical products.",
    "definition": "Shock events are classified as: 'Minor' (unlikely to cause damage), 'Moderate' (potential to damage if repeated), 'Severe' (likely to cause damage to product or packaging), with null values indicating no shock monitoring was implemented."
  },
  {
    "id": 24,
    "knowledge": "Cold Chain Vehicle Qualification Status",
    "description": "Illustrates the validation levels of vehicles used in pharmaceutical transport.",
    "definition": "Vehicles can be classified as: 'Validated' (fully validated through performance and temperature mapping studies), 'Qualified' (basic qualification but not fully validated), 'Unqualified' (not formally qualified for pharmaceutical transport)."
  },
  {
    "id": 25,
    "knowledge": "Time In Range Percentage (TIRP)",
    "description": "Calculates the percentage of time a shipment's temperature stayed within required parameters.",
    "definition": "TIRP = \\frac{T_{total} - TED}{T_{total}} \\times 100\\%, \\text{where } T_{total} \\text{ is the total transit time and TED is the Temperature Excursion Duration.}"
  },
  {
    "id": 26,
    "knowledge": "Mean Kinetic Temperature (MKT)",
    "description": "A calculated temperature that expresses the overall effect of temperature fluctuations during storage or transit.",
    "definition": "MKT = \\frac{-\\Delta H/R}{\\ln\\left(\\frac{\\sum_{i=1}^{n} e^{-\\Delta H/RT_i}}{n}\\right)}, \\text{where } \\Delta H \\text{ is the activation energy (usually 83.144 kJ/mol for pharmaceuticals), R is the gas constant (8.3144 J/mol/K), and } T_i \\text{ is each temperature point in Kelvin.}"
  },
  {
    "id": 27,
    "knowledge": "Quality Risk Zones",
    "description": "Identifies risk levels for temperature-sensitive products based on excursion metrics.",
    "definition": "Quality risk zones are: 'Green Zone' (TIRP > 98% and no excursions > 30 min), 'Yellow Zone' (95% \u2264 TIRP \u2264 98% or any excursion 30-60 min), 'Red Zone' (TIRP < 95% or any excursion > 60 min)."
  },
  {
    "id": 28,
    "knowledge": "Humidity Sensitivity Categories",
    "description": "Classifies pharmaceutical products based on their sensitivity to humidity variations.",
    "definition": "Humidity sensitivity categories are: 'Not Sensitive' (can tolerate wide humidity variations), 'Moderately Sensitive' (can tolerate limited humidity variations), 'Highly Sensitive' (requires strict humidity control), with null values indicating humidity sensitivity not specified."
  },
  {
    "id": 29,
    "knowledge": "Premium Transport Container Types",
    "description": "Identifies specialized containers used for high-value pharmaceutical transport.",
    "definition": "Premium transport containers include: Envirotainer RAP e2, Envirotainer RKN e1, va-Q-tainer USx, CSafe RKN, DoKaSch Opticooler, and Sonoco ThermoSafe PharmaPort 360."
  },
  {
    "id": 31,
    "knowledge": "Pharmaceutical Stability Budget",
    "description": "The total allowable time a product can spend outside of ideal conditions before quality is compromised.",
    "definition": "The maximum cumulative duration (typically specified in hours or days) that a pharmaceutical product can experience conditions outside its labeled storage requirements without significant impact to its quality, safety, or efficacy. Null values indicate stability budget has not been determined for the product."
  },
  {
    "id": 32,
    "knowledge": "Stability Budget Consumption Rate (SBCR)",
    "description": "Measures how quickly a shipment is consuming its allocated stability budget during transit.",
    "definition": "SBCR = \\frac{TED}{SB_{total}} \\times 100\\%, \\text{where TED is the Temperature Excursion Duration and } SB_{total} \\text{ is the total stability budget allocated for the product.}"
  },
  {
    "id": 33,
    "knowledge": "Package Integrity Monitoring Systems",
    "description": "Identifies technologies used to monitor physical integrity of packages during transit.",
    "definition": "Package integrity monitoring systems include: Shock Indicators (mechanical devices that show when a package has received an impact), Tilt Indicators (show if a package was tilted beyond acceptable angles), Electronic Impact Recorders (provide detailed shock measurements), and Pressure Indicators (monitor pressure changes in sealed containers)."
  },
  {
    "id": 34,
    "knowledge": "Product Release Decision Framework",
    "description": "Structured approach for determining if temperature-sensitive products can be released for use after transport.",
    "definition": "A decision framework considering: 1) Presence of temperature excursions, 2) Stability data for specific excursion profiles, 3) Package integrity, 4) Product appearance, and 5) Analytical testing results if required. Products can be 'Released' (meets all criteria), 'Released with CAPA' (meets essential criteria but requires corrective action), 'Quarantined' (requires further investigation), or 'Rejected' (failed critical criteria)."
  },
  {
    "id": 35,
    "knowledge": "Qualification Status of Temperature Monitoring Devices",
    "description": "Indicates the validation level of monitoring devices used in pharmaceutical transport.",
    "definition": "Monitoring devices can be: 'Fully Qualified' (calibrated with NIST-traceable standards and validated for pharmaceutical use), 'Partially Qualified' (calibrated but not fully validated), 'Unqualified' (not formally qualified), with null values indicating qualification status is unknown."
  },
  {
    "id": 36,
    "knowledge": "Lane Risk Potential (LRP)",
    "description": "Quantifies the risk associated with a specific shipping route based on historical performance.",
    "definition": "LRP = \\frac{TE_{total} + SD_{total} + CD_{total}}{N_{shipments}}, \\text{where } TE_{total} \\text{ is the total count of temperature excursions, } SD_{total} \\text{ is the total count of shipping delays, } CD_{total} \\text{ is the total count of customs delays, and } N_{shipments} \\text{ is the number of shipments on that lane.}"
  },
  {
    "id": 37,
    "knowledge": "Storage Temperature Requirements for Biologics",
    "description": "Specifies the standard temperature storage requirements for biological pharmaceutical products.",
    "definition": "Most biologics require storage at either '2-8\u00b0C' (refrigerated) or '-20\u00b0C' (frozen), with certain specialized biologic products requiring '-70\u00b0C' (ultra-low temperature) storage. Room temperature (15-25\u00b0C) storage is rarely suitable for biologics unless specifically formulated for stability at those temperatures."
  },
  {
    "id": 38,
    "knowledge": "Last Mile Delivery Risk",
    "description": "Specific risks associated with the final stage of pharmaceutical product delivery.",
    "definition": "Last mile delivery risks include: Lack of temperature-controlled vehicles, Multiple stops increasing door-opening frequency, Variable driver training in handling procedures, Inconsistent receiving procedures at destinations, and Limited monitoring capabilities compared to main transport segments."
  },
  {
    "id": 39,
    "knowledge": "Security Incident Severity Scale",
    "description": "Categorizes security events during pharmaceutical transport by their severity.",
    "definition": "Security incidents are classified on a scale of 0-4: '0' (No security concerns), '1' (Minor procedural deviation), '2' (Moderate security concern without evidence of tampering), '3' (Clear evidence of attempted tampering), '4' (Confirmed breach with product access), with null values indicating security assessment was not performed."
  },
  {
    "id": 40,
    "knowledge": "Temperature Profile Categorization",
    "description": "Classifies the pattern of temperature readings during a shipment.",
    "definition": "Temperature profiles are categorized as: 'Stable' (minimal variations within range), 'Cyclic' (regular patterns of variation within range), 'Trend' (gradual increase or decrease over time), 'Excursion' (periods outside acceptable range), or 'Erratic' (unpredictable variations suggesting monitoring issues)."
  },
  {
    "id": 41,
    "knowledge": "Excursion Impact Assessment (EIA)",
    "description": "Evaluates the potential quality impact of temperature excursions on product.",
    "definition": "EIA = \\sum_{i=1}^{n} (|T_i - T_{limit}| \\times t_i), \\text{where } T_i \\text{ is the temperature during excursion } i, T_{limit} \\text{ is the nearest temperature limit (upper or lower), and } t_i \\text{ is the duration of excursion } i \\text{ in hours.}"
  },
  {
    "id": 42,
    "knowledge": "Primary Cold Chain Monitoring Authorities",
    "description": "Key regulatory bodies that oversee cold chain management for pharmaceuticals.",
    "definition": "Primary regulatory authorities for pharmaceutical cold chains include: FDA (US Food and Drug Administration), EMA (European Medicines Agency), MHRA (UK Medicines and Healthcare products Regulatory Agency), Health Canada, TGA (Australian Therapeutic Goods Administration), PMDA (Japanese Pharmaceuticals and Medical Devices Agency), and WHO (World Health Organization)."
  },
  {
    "id": 43,
    "knowledge": "Package Thermal Efficiency Rating",
    "description": "Measures how effectively a packaging system maintains internal temperature despite external conditions.",
    "definition": "Thermal efficiency rating is classified as: 'Basic' (<24 hours of protection), 'Standard' (24-48 hours of protection), 'Enhanced' (48-96 hours of protection), 'Extended' (>96 hours of protection)."
  },
  {
    "id": 44,
    "knowledge": "Risk-Based Monitoring Intensity",
    "description": "Determines appropriate monitoring frequency based on product risk profile.",
    "definition": "High-risk products (biologics, vaccines) require continuous temperature monitoring with 5-minute intervals, medium-risk products should have 15-minute intervals, and low-risk products can use 30-minute intervals, with null values in monitoring frequency indicating unplanned or non-standardized monitoring approaches."
  },
  {
    "id": 45,
    "knowledge": "Cold Chain Cost Efficiency Ratio (CCER)",
    "description": "Measures the relationship between cold chain protection costs and product value.",
    "definition": "CCER = \\frac{C_{monitoring} + C_{packaging} + C_{transport}}{V_{product}} \\times 100\\%, \\text{where } C_{monitoring}, C_{packaging}, C_{transport} \\text{ are the respective costs, and } V_{product} \\text{ is the product value.}"
  },
  {
    "id": 46,
    "knowledge": "Quality Management System Maturity Model",
    "description": "Framework for assessing the sophistication of a cold chain quality management system.",
    "definition": "QMS maturity levels range from Level 1 (Basic: minimal documentation and reactive approaches) to Level 5 (Optimized: fully integrated systems with continuous improvement). Intermediate levels include Level 2 (Developing: standard procedures established), Level 3 (Defined: processes are well-documented and followed), and Level 4 (Managed: processes are measured and controlled)."
  },
  {
    "id": 47,
    "knowledge": "Thermodynamic Stability Class",
    "description": "Categorizes pharmaceutical products based on their thermal stability characteristics.",
    "definition": "Products are classified as: Class A (highly stable, can tolerate brief temperature excursions with minimal degradation), Class B (moderately stable), Class C (limited stability, requires strict temperature control), and Class D (highly unstable, no temperature excursions permitted)."
  },
  {
    "id": 48,
    "knowledge": "Data Logger Reliability Score (DLRS)",
    "description": "Assesses the reliability of temperature monitoring devices based on historical performance.",
    "definition": "DLRS = 100 - (10 \\times F_r + 5 \\times F_d + 3 \\times F_c + 2 \\times F_b), \\text{where } F_r \\text{ is the rate of reading failures, } F_d \\text{ is the rate of download failures, } F_c \\text{ is the calibration drift rate, and } F_b \\text{ is the battery failure rate. All rates are per 100 deployments.}"
  },
  {
    "id": 49,
    "knowledge": "Acceptable Temperature Deviation Limits",
    "description": "Industry standards for tolerable temperature deviations during pharmaceutical transport.",
    "definition": "For refrigerated products (2-8\u00b0C): brief excursions (< 30 min) to 0-12\u00b0C may be acceptable; For frozen products (-20\u00b0C): brief excursions to -15\u00b0C may be acceptable; For ultra-frozen products (-70\u00b0C): brief excursions to -60\u00b0C may be acceptable; For controlled room temperature products (15-25\u00b0C): brief excursions to 10-30\u00b0C may be acceptable."
  },
  {
    "id": 50,
    "knowledge": "Last Mile Delivery Metrics",
    "description": "Key performance indicators specific to final stage pharmaceutical delivery.",
    "definition": "Key last mile metrics include: First Attempt Delivery Success Rate, Temperature Deviation Frequency, Receiver Wait Time, Documentation Completion Rate, and Handler Qualification Status."
  },
  {
    "id": 51,
    "knowledge": "Batch Release Critical Path Elements",
    "description": "The essential components required before a temperature-sensitive product batch can be released.",
    "definition": "Critical path elements include: Complete temperature history with no unexplained gaps, Confirmation that any excursions were within stability budgets, Intact security seals or acceptable explanation for compromised seals, Complete chain of custody documentation, and Acceptable visual inspection results."
  },
  {
    "id": 52,
    "knowledge": "Electronic Monitoring System Tiers",
    "description": "Classification of monitoring systems based on their capabilities and features.",
    "definition": "Electronic monitoring systems are classified as: Tier 1 (basic data loggers with manual download), Tier 2 (enhanced loggers with USB or Bluetooth download), Tier 3 (network-connected devices with real-time alerts), and Tier 4 (fully integrated IoT systems with predictive capabilities and automated interventions)."
  },
  {
    "id": 53,
    "knowledge": "Validation Documentation Requirements",
    "description": "The essential documentation needed to validate cold chain processes and equipment.",
    "definition": "Required validation documents include: Validation Master Plan, Risk Assessment, User Requirements Specification, Design Qualification, Installation Qualification, Operational Qualification, Performance Qualification, Temperature Mapping Studies, and Final Validation Report."
  },
  {
    "id": 54,
    "knowledge": "Serialization Maturity Model",
    "description": "Framework for assessing pharmaceutical tracking and tracing capabilities.",
    "definition": "Serialization maturity levels are: Level 0 (No serialization), Level 1 (Batch-level tracking only), Level 2 (Package-level serialization without systematic verification), Level 3 (Verified package-level serialization), and Level 4 (End-to-end serialized supply chain with real-time visibility)."
  },
  {
    "id": 55,
    "knowledge": "Monitoring Device Calibration Status",
    "description": "Indicates if temperature monitoring devices are properly calibrated for accurate readings.",
    "definition": "Calibration status includes: 'Current' (calibrated within required timeframe, typically 12 months), 'Expired' (calibration period has elapsed), 'Exempt' (single-use devices with factory calibration), with null values indicating calibration status is unknown or not documented."
  },
  {
    "id": 56,
    "knowledge": "GDP Corrective Action Categories",
    "description": "Standard categories for corrective actions in Good Distribution Practice.",
    "definition": "GDP corrective action categories include: Training Enhancement, Documentation Update, Process Modification, Equipment Upgrade, Supplier Management, Transport Adjustment, Monitoring Improvement, and Regulatory Compliance Actions."
  },
  {
    "id": 57,
    "knowledge": "Temperature Accuracy Impact Factor (TAIF)",
    "description": "Quantifies the potential error in product status assessment due to monitoring device accuracy limitations.",
    "definition": "TAIF = \\frac{|T_{max} - T_{upper}|}{A} + \\frac{|T_{min} - T_{lower}|}{A}, \\text{where } T_{max} \\text{ and } T_{min} \\text{ are the maximum and minimum recorded temperatures, } T_{upper} \\text{ and } T_{lower} \\text{ are the upper and lower temperature limits, and } A \\text{ is the stated accuracy of the monitoring device in \u00b0C.}"
  },
  {
    "id": 58,
    "knowledge": "Vehicle Temperature Monitoring Types",
    "description": "Methods used to monitor temperatures in transport vehicles.",
    "definition": "Vehicle temperature monitoring types include: 'Continuous' (uninterrupted monitoring throughout transport), 'Interval' (periodic checks at predetermined times), 'None' (no active monitoring), with null values indicating monitoring type was not specified in documentation."
  },
  {
    "id": 59,
    "knowledge": "Data Integrity Components",
    "description": "Essential elements that ensure cold chain data is reliable for decision-making.",
    "definition": "Data integrity components include the ALCOA+ principles: Attributable (traceable to individual/system), Legible (readable and permanent), Contemporaneous (recorded at time of activity), Original (source data or certified copy), Accurate (error-free), plus Complete (all data included), Consistent (expected sequence followed), Enduring (preserved for required period), and Available (accessible when needed)."
  }
]

