submit('CREATE OR REPLACE FUNCTION get_spread_rate(p_exch_spot text)
RETURNS numeric AS $$
DECLARE
    v_spread numeric;
BEGIN
    SELECT (orderbook_metrics->>''spread_abs'')::numeric
    INTO v_spread
    FROM marketdata
    WHERE EXCH_SPOT = p_exch_spot;

    RETURN v_spread;
END;
$$ LANGUAGE plpgsql IMMUTABLE;')

execute("""CREATE OR REPLACE FUNCTION get_spread_rate(p_exch_spot text)
RETURNS numeric AS $$
DECLARE
    v_spread_pct text;
    v_spread_rate numeric;
BEGIN
    SELECT orderbook_metrics->>'spread_pct'
    INTO v_spread_pct
    FROM marketdata
    WHERE EXCH_SPOT = p_exch_spot;

    IF v_spread_pct IS NULL THEN
        RETURN NULL;
    END IF;

    -- Remove the trailing '%' and convert to numeric, then divide by 100 to get a decimal rate
    v_spread_rate := replace(v_spread_pct, '%', '')::numeric / 100.0;
    RETURN v_spread_rate;
END;
$$ LANGUAGE plpgsql IMMUTABLE;""")

submit('CREATE OR REPLACE FUNCTION get_spread_rate(p_exch_spot text)
RETURNS numeric AS $$
DECLARE
    v_spread_pct text;
    v_spread_rate numeric;
BEGIN
    SELECT orderbook_metrics->>''spread_pct''
    INTO v_spread_pct
    FROM marketdata
    WHERE EXCH_SPOT = p_exch_spot;

    IF v_spread_pct IS NULL THEN
        RETURN NULL;
    END IF;

    -- Remove the trailing ''%'' and convert to numeric, then divide by 100 to get a decimal rate
    v_spread_rate := replace(v_spread_pct, ''%'', '''')::numeric / 100.0;
