[
  {
    "id": 0,
    "knowledge": "Disaster Mortality Rate (DMR)",
    "description": "Calculates the percentage of the affected population that resulted in fatalities.",
    "definition": "The percentage of a disaster's total affected population that resulted in a confirmed death."
  },
  {
    "id": 1,
    "knowledge": "Population Displacement Rate (PDR)",
    "description": "Measures the percentage of the affected population that has been displaced from their homes.",
    "definition": "The percentage of a disaster's total affected population that has been forced to leave their homes."
  },
  {
    "id": 2,
    "knowledge": "Infrastructure Damage Index (IDI)",
    "description": "A composite score from 0 to 100 that quantifies the overall damage to critical infrastructure.",
    "definition": "A composite score calculated as the average of infrastructure, power, and water damage percentages. Formula: (COALESCE(infra_damage_pct, 0) + COALESCE(power_outage_pct, 0) + COALESCE(water_damage_pct, 0)) / 3."
  },
  {
    "id": 3,
    "knowledge": "Supply Sufficiency (Days)",
    "description": "Estimates for how many days the current supplies can last. This is determined by the most limiting resource (either food or water).",
    "definition": "Calculates the minimum number of days supplies can last, assuming a daily consumption of 2kg of food and 3 liters of water per person. Formula: LEAST((food_tons * 1000) / (affected_population * 2), water_liters / (affected_population * 3))."
  },
  {
    "id": 4,
    "knowledge": "Financial Burn Rate (FBR)",
    "description": "Calculates the average daily operational spending from the allocated budget.",
    "definition": "The average daily expenditure of an operation. Formula: total_operational_costs / (current_date - operation_start_date)."
  },
  {
    "id": 5,
    "knowledge": "Cost Per Person Affected (CPPA)",
    "description": "Calculates the total operational cost incurred per person in the affected population.",
    "definition": "The total cost of an operation divided by the affected population. Total cost is the sum of ops_costs_usd, transportcostsUSD, storage_costs_usd, and personnelcostsUsd."
  },
  {
    "id": 6,
    "knowledge": "Logistical Throughput per Vehicle (LTV)",
    "description": "Measures the average daily delivery capacity in tons per available transport vehicle.",
    "definition": "The average daily tonnage delivered per vehicle. Formula: daily_tons / vehicle_count."
  },
  {
    "id": 7,
    "knowledge": "Hub Strain Index (HSI)",
    "description": "A score indicating the operational pressure on a distribution hub, considering both its internal metrics and the severity of the disasters it serves.",
    "definition": "A score blending internal stress and external demand. Formula: (0.5 * ((hubUtilPct / 100) + (stockTurnRate / 10))) + (0.5 * avg_dsi_served)."
  },
  {
    "id": 8,
    "knowledge": "Population Impact Score (PIS)",
    "description": "A weighted score quantifying the overall human impact of a disaster.",
    "definition": "A weighted score measuring human suffering, calculated with the formula: (10 * COALESCE(casualties, 0)) + (3 * COALESCE(injured, 0)) + (2 * COALESCE(missing, 0)) + (1 * COALESCE(displaced, 0))."
  },
  {
    "id": 9,
    "knowledge": "Medical Support Ratio (MSR)",
    "description": "Calculates the ratio of medical staff to the total number of casualties and injured, indicating direct medical response capacity.",
    "definition": "The ratio of available medical personnel to the total number of casualties and injured. Formula: medical_personnel / (casualties + injured)."
  },
  {
    "id": 10,
    "knowledge": "Aid Delivery Cost per Ton (ADC)",
    "description": "Calculates the average transportation cost to deliver one ton of supplies.",
    "definition": "The total transport costs for a given transport ID, divided by the total tons delivered by that same transport ID."
  },
  {
    "id": 11,
    "knowledge": "Budget Runway (Days)",
    "description": "Estimates the number of days until the allocated budget is depleted, based on the current burn rate.",
    "definition": "The estimated number of days an operation can continue before its budget is exhausted. Formula: (allocated_budget - total_operational_costs) / Financial Burn Rate."
  },
  {
    "id": 12,
    "knowledge": "Shelter Gap",
    "description": "Calculates the shortfall in shelter units relative to the displaced population.",
    "definition": "The difference between the number of displaced individuals and the number of available shelter units. Formula: GREATEST(0, displaced_population - shelter_units)."
  },
  {
    "id": 13,
    "knowledge": "Operational Readiness Score (ORS)",
    "description": "A score from 0 to 100 assessing the readiness of the response team and their equipment.",
    "definition": "A composite score indicating a team's preparedness, based on personnel availability, equipment status, and maintenance levels."
  },
  {
    "id": 14,
    "knowledge": "Response Effectiveness Score (RES)",
    "description": "A composite score measuring the overall effectiveness of the response operation.",
    "definition": "A weighted score of an operation's success. Formula: (0.4 * success_rate) + (0.3 * bene_feedbackscore * 10) + (0.3 * distequityidx * 100)."
  },
  {
    "id": 16,
    "knowledge": "Overall Disaster Severity Index (DSI)",
    "description": "A comprehensive index combining human and infrastructural impact into a single severity score.",
    "definition": "A composite index calculated by the formula: (0.6 * Population Impact Score) + (0.4 * Infrastructure Damage Index)."
  },
  {
    "id": 17,
    "knowledge": "Total Humanitarian Footprint (THF)",
    "description": "A measure of the total personnel involved in the response, including staff and volunteers.",
    "definition": "The total number of personnel, including both paid staff and volunteers, dedicated to a response operation."
  },
  {
    "id": 18,
    "knowledge": "Supply Chain Fragility Index (SCFI)",
    "description": "A score indicating the vulnerability of a supply chain, considering both hub strain and vehicle reliability.",
    "definition": "A score assessing supply chain vulnerability. Formula: (0.5 * ((hubutilpct / 100) + (stockturnrate / 10))) + (0.5 * break_rate)."
  },
  {
    "id": 19,
    "knowledge": "Public Health Risk Score (PHRS)",
    "description": "A score assessing the overall public health risk, calculated from medical support, disease risk, sanitation, and water quality.",
    "definition": "A composite risk score based on multiple factors. It is calculated by first deriving component scores: disease_risk_score (High=3, Medium=2, else 1), sanitation_risk (100 - sanitation_coverage), and water_quality_risk (100 - water_quality_index). The final formula is: ((1 - MSR) * 40) + (disease_risk_score * 10) + (sanitation_risk * 0.15) + (water_quality_risk * 0.15)."
  },
  {
    "id": 20,
    "knowledge": "Financial Health Score (FHS)",
    "description": "An index assessing the financial stability of an operation based on budget and spending.",
    "definition": "A score assessing financial stability, calculated by averaging the budget remaining percentage and funding sufficiency. Formula: 0.5 * (100 - funds_util_pct) + 0.5 * ((budgetallotusd - COALESCE(resource_gaps_usd, 0)) / NULLIF(budgetallotusd, 0)) * 100."
  },
  {
    "id": 21,
    "knowledge": "Mass Casualty Incident (MCI)",
    "description": "An event with a number of casualties that overwhelms or significantly challenges the available medical resources.",
    "definition": "An event is classified as an 'MCI' if the total number of fatalities and injuries is greater than 100, OR if the Medical Support Ratio (MSR) is less than 0.01."
  },
  {
    "id": 23,
    "knowledge": "Imminent Supply Depletion Alert",
    "description": "A critical warning that essential life-sustaining supplies will run out within 48 hours.",
    "definition": "An 'Imminent Supply Depletion Alert' is triggered when the calculated Supply Sufficiency (Days) is less than 2."
  },
  {
    "id": 24,
    "knowledge": "Funding Crisis",
    "description": "An operational state where an operation is at immediate risk of halting due to lack of funds, characterized by a 'Critical' funding status and a very short budget runway.",
    "definition": "A 'Funding Crisis' is active when the operation's funding state is 'Critical' and its estimated Budget Runway is less than 7 days."
  },
  {
    "id": 25,
    "knowledge": "Logistical Gridlock",
    "description": "A severe breakdown in the supply chain, rendering aid delivery ineffective.",
    "definition": "A 'Logistical Gridlock' is identified if the supply flow state is 'Disrupted' AND transportation access is 'Minimal'."
  },
  {
    "id": 26,
    "knowledge": "Public Health Emergency",
    "description": "A state where the risk of disease is high and the capacity to respond is critically low.",
    "definition": "A 'Public Health Emergency' exists if the Public Health Risk Score (PHRS) exceeds a critical threshold of 70."
  },
  {
    "id": 27,
    "knowledge": "High-Risk Operation",
    "description": "An operation facing severe security threats or access constraints that endanger personnel and mission objectives.",
    "definition": "An operation is 'High-Risk' if it has a 'High Risk' safety ranking OR if the number of security incidents exceeds 5 per week."
  },
  {
    "id": 28,
    "knowledge": "Highly Effective Operation",
    "description": "An operation that demonstrates excellence across coordination, logistics, and beneficiary satisfaction.",
    "definition": "An operation is 'Highly Effective' if its Response Effectiveness Score (RES) is greater than 75 AND its Coordination Quality Index (CQI) is greater than 75."
  },
  {
    "id": 29,
    "knowledge": "Severe Shelter Crisis",
    "description": "A critical lack of adequate shelter for the displaced population.",
    "definition": "A 'Severe Shelter Crisis' is active if the calculated Shelter Gap is greater than 1,000 units."
  },
  {
    "id": 30,
    "knowledge": "Major Disaster",
    "description": "Classifies a disaster as 'Major' based on the comprehensive severity index, indicating a need for national-level response.",
    "definition": "A 'Major Disaster' is any event where the Overall Disaster Severity Index (DSI) is between 500,000 and 2,000,000."
  },
  {
    "id": 31,
    "knowledge": "Overwhelmed Logistical Hub",
    "description": "Flags a distribution hub that is under extreme pressure and likely a bottleneck in the supply chain.",
    "definition": "A hub is 'Overwhelmed' if its Hub Strain Index (HSI) is greater than 1,000,000."
  },
  {
    "id": 32,
    "knowledge": "Failing Operation",
    "description": "An operation characterized by poor logistical performance and low effectiveness.",
    "definition": "An operation is 'Failing' if its Logistical Throughput per Vehicle (LTV) is below 1.0 OR its Response Effectiveness Score (RES) is below 40."
  },
  {
    "id": 33,
    "knowledge": "Full-Scale Emergency",
    "description": "Defines the criteria for a full-scale emergency response.",
    "definition": "A 'Full-Scale Emergency' is any operation where the emergency level is 'Red' or 'Black'."
  },
  {
    "id": 34,
    "knowledge": "Successful Community Partnership",
    "description": "Identifies operations with excellent community relations and equitable aid distribution.",
    "definition": "A 'Successful Community Partnership' exists when community engagement is 'High' and the distribution equity index is greater than 0.9."
  },
  {
    "id": 35,
    "knowledge": "High Cost, Low Impact Operation",
    "description": "An operation that is financially expensive but is having little positive effect on the ground.",
    "definition": "An operation is 'High Cost, Low Impact' if its Cost Per Person Affected (CPPA) is above average AND its Response Effectiveness Score (RES) is below average."
  },
  {
    "id": 36,
    "knowledge": "Operation with Fragile Supply Chain",
    "description": "Identifies an operation whose logistics are at high risk of failure.",
    "definition": "An operation has a 'Fragile Supply Chain' if its Supply Chain Fragility Index (SCFI) is greater than 5.0."
  },
  {
    "id": 37,
    "knowledge": "Financially Unstable Operation",
    "description": "An operation with poor financial health, indicating a risk of budget overruns or failure to meet objectives.",
    "definition": "An operation is 'Financially Unstable' if its Financial Health Score (FHS) is below 50."
  },
  {
    "id": 38,
    "knowledge": "High-Accountability Response",
    "description": "A response characterized by strong compliance, documentation, and quality control.",
    "definition": "A 'High-Accountability Response' is one where the compliance state is 'Compliant', the audit state is 'Completed', and quality control steps are 'Strong'."
  },
  {
    "id": 39,
    "knowledge": "Negative Media Narrative",
    "description": "A situation where public and media perception of the response effort is poor.",
    "definition": "A 'Negative Media Narrative' is present if the media coverage sentiment is 'Negative' and the public perception score is below 60."
  },
  {
    "id": 40,
    "knowledge": "Gridlock Severity Index (GSI)",
    "description": "A weighted score to prioritize operations in logistical gridlock, based on mission priority, personnel count, and transport access restrictions.",
    "definition": "A weighted sum calculated after converting categorical data to scores: priority_rank ('critical'=1 to 'low'=4) and transport_access ('minimal'=1.0, 'limited'=0.5). The final formula is: ((10 - priority_score) * 0.5) + (total_personnel * 0.2) + (transport_restriction_score * 30)."
  },
  {
    "id": 41,
    "knowledge": "Hazard Severity Levels",
    "description": "A classification of a disaster's intensity, guiding the scale of the required response.",
    "definition": "'Level 1' indicates a minor, localized event. 'Level 3' indicates a moderate event with regional impact. 'Level 5' indicates a catastrophic event with widespread, severe impact requiring international assistance."
  },
  {
    "id": 42,
    "knowledge": "Emergency Alert Levels",
    "description": "Color-coded levels that define the urgency and command structure for an ongoing operation.",
    "definition": "'Yellow': Monitoring required. 'Orange': Active response, regional command. 'Red': Full-scale emergency, national command. 'Black': Catastrophic event, international-level coordination."
  },
  {
    "id": 43,
    "knowledge": "Response Phases",
    "description": "The distinct phases of a disaster management cycle, from immediate action to long-term rebuilding.",
    "definition": "'Initial': First 24-72 hours, focus on life-saving. 'Emergency': Period of active, large-scale relief. 'Recovery': Transition to restoring services. 'Reconstruction': Long-term rebuilding of infrastructure and society."
  },
  {
    "id": 44,
    "knowledge": "Distribution Equity Index",
    "description": "An index from 0 to 1 that measures the fairness and impartiality of aid distribution among affected populations.",
    "definition": "A score of 1.0 represents perfect equity. A score below 0.7 may indicate significant disparities. A score below 0.5 indicates severe inequity."
  },
  {
    "id": 45,
    "knowledge": "Damage Report Categories",
    "description": "A qualitative assessment of the physical destruction caused by a disaster.",
    "definition": "'Minor': Limited damage. 'Moderate': Visible damage to some structures. 'Severe': Widespread destruction. 'Catastrophic': Near-total destruction of the built environment in the affected area."
  },
  {
    "id": 46,
    "knowledge": "Coordination Effectiveness Levels",
    "description": "A rating of how well different agencies, government bodies, and NGOs are working together.",
    "definition": "'Low': Poor communication, duplicated efforts. 'Medium': Functional coordination with some gaps. 'High': Seamless, efficient, and collaborative partnership among all stakeholders."
  },
  {
    "id": 47,
    "knowledge": "Funding States",
    "description": "Describes the financial health of an operation in relation to its needs.",
    "definition": "'Adequate': Sufficient funds are available. 'Limited': Funding is available but does not cover all needs, requiring prioritization. 'Critical': A severe funding gap threatens essential activities."
  },
  {
    "id": 48,
    "knowledge": "Data Quality Value",
    "description": "A score from 0 to 100 representing the reliability, completeness, and timeliness of the data being reported.",
    "definition": "A score above 90 is 'Excellent'. 70-89 is 'Good'. 50-69 is 'Fair'. Below 50 is 'Poor' and indicates that operational decisions are based on unreliable information."
  },
  {
    "id": 49,
    "knowledge": "Supply Flow States",
    "description": "Describes the overall health and functionality of the supply chain for a relief operation.",
    "definition": "'Stable': Goods are moving predictably and efficiently. 'Strained': The supply chain is functioning but experiencing delays or difficulties. 'Disrupted': The supply chain is broken, and goods are not reaching their destinations."
  },
  {
    "id": 50,
    "knowledge": "Last-Mile Delivery Status",
    "description": "The status of the final and most critical stage of delivery, from a local hub to the final distribution points.",
    "definition": "'On Track': Deliveries are proceeding as planned. 'Delayed': Deliveries are facing obstacles and are behind schedule. 'Suspended': Deliveries have been halted due to safety, access, or other critical issues."
  },
  {
    "id": 51,
    "knowledge": "Catastrophic Disaster",
    "description": "Classifies a disaster as 'Catastrophic' based on the DSI, indicating a need for maximum-level international response.",
    "definition": "A 'Catastrophic Disaster' is any event where the Overall Disaster Severity Index (DSI) is greater than 15,000."
  },
  {
    "id": 52,
    "knowledge": "Cost Per Beneficiary (CPB)",
    "description": "Calculates the overall average cost to assist a single beneficiary, based on the total costs of completed operations divided by the total number of people affected.",
    "definition": "Calculated by dividing the total costs by the total affected population. Total costs are the sum of ops_costs_usd, transportcostsUSD, storage_costs_usd, and personnelcostsUsd."
  },
  {
    "id": 53,
    "knowledge": "Average Vehicle Breakdown Rate",
    "description": "Calculates the mean vehicle breakdown rate for a specified cohort of transportation units.",
    "definition": "The mean rate at which transport vehicles become non-operational, calculated for a specific group of vehicles. The underlying 'break_rate' data is stored as a percentage."
  },
  {
    "id": 54,
    "knowledge": "High Risk Operation",
    "description": "An active operation with significant safety or security concerns.",
    "definition": "An operation is considered 'High Risk' if its status is 'Active' AND its safety ranking is 'High Risk' OR it has more than 5 security incidents."
  },
  {
    "id": 55,
    "knowledge": "Medical Staff Ratio",
    "description": "The number of medical staff available per 1000 affected people.",
    "definition": "A ratio indicating medical staff availability. Formula: (medical_staff_count / affected_population) * 1000."
  },
  {
    "id": 56,
    "knowledge": "Hub Overload",
    "description": "A state where a distribution hub's operational metrics indicate it is under excessive strain.",
    "definition": "A hub is considered overloaded if its combined utilization and turnover score is greater than 1.5. Formula: (hubutilpct / 100) + (stockturnrate / 10) > 1.5."
  },
  {
    "id": 57,
    "knowledge": "High Burn Rate Alert",
    "description": "An alert for operations that have consumed a significant portion of their budget.",
    "definition": "A 'High Burn Rate' alert is triggered for an operation if its total costs exceed 20% of its total allocated budget."
  },
  {
    "id": 58,
    "knowledge": "Fragile Supply Chain",
    "description": "Identifies operations whose logistical infrastructure is considered unstable or at risk.",
    "definition": "An operation is considered to have a 'Fragile Supply Chain' if its Supply Chain Fragility Index (SCFI) is greater than 5.0."
  }
]

